mapper.select:
SELECT h.monitor_chk_rmk
  FROM tbl_ccp_verify_check h
 WHERE h.co_cd = #{coCd}
   AND h.doc_idx = #{docIdx}

mapper.update:
UPDATE tbl_ccp_verify_check
   SET monitor_chk_rmk = NULLIF(#{monitorChkRmk}, ''),
       upd_id = #{userId},
       upd_dt = now()
 WHERE co_cd = #{coCd}
   AND doc_idx = #{docIdx}
